MAXV = 2147483647
MINV = -2147483648


def tokens(text):
    out, i, n = [], 0, len(text)
    while i < n:
        c = text[i]
        if c in " \t":
            i += 1
        elif c in "+-*/%()":
            out.append(c)
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < n and "0" <= text[j] <= "9":
                j += 1
            lit = text[i:j]
            if (len(lit) > 1 and lit[0] == "0") or int(lit) > MAXV:
                raise ValueError("bad literal")
            out.append(lit)
            i = j
        else:
            raise ValueError("bad character")
    return out


class _Parser:
    def __init__(self, toks):
        self.t, self.i, self.rpn, self.depth, self.maxdepth = toks, 0, [], 0, 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else None

    def expr(self):
        self.term()
        while self.peek() in ("+", "-"):
            op = self.t[self.i]
            self.i += 1
            self.term()
            self.rpn.append(op)

    def term(self):
        self.unary()
        while self.peek() in ("*", "/", "%"):
            op = self.t[self.i]
            self.i += 1
            self.unary()
            self.rpn.append(op)

    def unary(self):
        if self.peek() == "-":
            self.i += 1
            self.unary()
            self.rpn.append("neg")
        else:
            self.primary()

    def primary(self):
        p = self.peek()
        if p is None:
            raise ValueError("missing operand")
        if p == "(":
            self.i += 1
            self.depth += 1
            if self.depth > 200:
                raise ValueError("nesting too deep")
            self.maxdepth = max(self.maxdepth, self.depth)
            self.expr()
            if self.peek() != ")":
                raise ValueError("missing )")
            self.i += 1
            self.depth -= 1
        elif p[0].isdigit() and p.isascii():
            self.rpn.append(p)
            self.i += 1
        else:
            raise ValueError("unexpected token")


def _parse(text):
    p = _Parser(tokens(text))
    p.expr()
    if p.peek() is not None:
        raise ValueError("trailing tokens")
    return p


def _fit(v):
    if v < MINV or v > MAXV:
        raise OverflowError("overflow")
    return v


def eval_expr(text):
    st = []
    for tok in _parse(text).rpn:
        if tok == "neg":
            st.append(_fit(-st.pop()))
        elif tok in "+-*/%" and len(tok) == 1:
            b, a = st.pop(), st.pop()
            if tok == "+":
                st.append(_fit(a + b))
            elif tok == "-":
                st.append(_fit(a - b))
            elif tok == "*":
                st.append(_fit(a * b))
            else:
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                st.append(_fit(a // b) if tok == "/" else a % b)
        else:
            st.append(int(tok))
    return st[0]


def depth(text):
    return _parse(text).maxdepth


def rpn(text):
    return _parse(text).rpn

